import{_ as r,c as e,o as t,af as n}from"./chunks/framework.BKeRpnBD.js";const c=JSON.parse('{"title":"典籍導讀","description":"典籍導讀，整理自 App 的免費易經學習文檔。","frontmatter":{"title":"典籍導讀","description":"典籍導讀，整理自 App 的免費易經學習文檔。"},"headers":[],"relativePath":"articles/references/index.md","filePath":"articles/references/index.md"}'),l={name:"articles/references/index.md"};function o(s,a,i,p,h,g){return t(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="高島易斷-高島吞象-1832–1914" tabindex="-1">高島易斷（高島吞象，1832–1914） <a class="header-anchor" href="#高島易斷-高島吞象-1832–1914" aria-label="Permalink to “高島易斷（高島吞象，1832–1914）”">​</a></h1><p><strong>《高島易斷》</strong>是日本明治期著名的易佔著作。作者通稱<strong>高島吞象</strong>，本名<strong>高島嘉右衛門</strong>，活躍於開港後的<strong>橫濱</strong>，兼具實業家與易佔家身分。</p><p>下面用一條更「可讀的故事線」，把高島吞象與《周易》的相遇、轉折、以及他如何把占筮帶回人間煙火講清楚。</p><h2 id="一條故事線-從牢獄到《易》" tabindex="-1">一條故事線：從牢獄到《易》 <a class="header-anchor" href="#一條故事線-從牢獄到《易》" aria-label="Permalink to “一條故事線：從牢獄到《易》”">​</a></h2><p>據傳，高島吞象早年經商，既要承擔家業與債務，也在劇烈變動的時代裡摸索出路。因涉足當時敏感的貨幣兌換牟利（利用金銀比價差），最終<strong>被捕入獄</strong>。</p><p>獄中環境惡劣、秩序混亂，生死往往只在一線。就在那樣的地方，他偶然見到一本被遺落的<strong>《易經》</strong>。那不是「算命的小冊子」，而是一套能把人心從恐懼裡拉回秩序的語言：卦象教人看形勢，卦辭教人辨方向，爻辭教人守進退。</p><p>他在獄中無事可做，便日夜研讀，甚至以紙捻作筮草，替囚犯占卦。占卜在牢房裡原是苦中作樂，卻因屢屢應驗而漸成信心——從此，《易》不再只是書頁上的古文，而變成能照見現實的鏡子。</p><h2 id="越獄與一卦-履之井" tabindex="-1">越獄與一卦：履之井 <a class="header-anchor" href="#越獄與一卦-履之井" aria-label="Permalink to “越獄與一卦：履之井”">​</a></h2><p>傳記裡最戲劇的一段，是<strong>越獄</strong>。同囚策畫逃亡，他以風險過大而拒絕，並佔得「<strong>履之井</strong>」：履，如踏虎尾，兇險逼人卻未必立刻受害；井，繩索升降，於困局中仍有一線生機。</p><p>後來越獄仍然爆發，兵刃圍堵、囚犯躁動，局勢迅速失控。據說他在混亂中負傷，卻於千鈞一髮之際，沿著牢內晾衣的繩索攀上，在衣物之間藏身，竟得以逃過屠戮——那一刻，他才真正讀懂「井」：不是井水，而是<strong>繩</strong>；不是奔逃，而是<strong>借勢而升</strong>。</p><p>不論細節如何流傳，這段故事留下一個核心：高島把卦當成「吉凶標籤」，也把卦當成「行動提示」。危險不是被消除，而是被看見、被安排、被穿過。</p><h2 id="出獄之後-以卦助人-也以卦成事" tabindex="-1">出獄之後：以卦助人，也以卦成事 <a class="header-anchor" href="#出獄之後-以卦助人-也以卦成事" aria-label="Permalink to “出獄之後：以卦助人，也以卦成事”">​</a></h2><p>據說他後來因為占卜屢驗，甚至被獄方請教，最終得以<strong>減刑出獄</strong>。出獄後他轉往橫濱，在新舊交錯的城市裡重建人生：</p><ul><li>作為<strong>實業家</strong>：經營木材事業，參與旅館等近代設施，亦涉足城市建設與交通（如鐵路）等議題。</li><li>作為<strong>易佔家</strong>：面向平民、商人乃至時局要事，以卦象爻義提供決策參考；並以大量佔例把方法整理成書，成為後人研讀的材料。</li></ul><p>另一段廣為人知的傳說是：他曾以佔象力勸某位要人避免遠行，但最終仍未能阻止悲劇發生。這讓人看到《易》的另一面：占筮不保證改寫命運，卻常常提供「<strong>提前知道代價</strong>」的機會。</p><h2 id="高島與《周易》-他延續了什麼" tabindex="-1">高島與《周易》：他延續了什麼 <a class="header-anchor" href="#高島與《周易》-他延續了什麼" aria-label="Permalink to “高島與《周易》：他延續了什麼”">​</a></h2><p>《周易》在中國古代形成——相傳伏羲畫八卦，文王、周公推演成卦爻辭，孔子及後儒整理「十翼」而成經典體系。易學不僅是哲學，也成為占筮的方法。</p><p>高島吞象的貢獻，不在於「另造一部易」，而在於把《周易》重新帶回一種可操作的秩序：<strong>以卦辭爻辭為核心，落到具體人事與決策</strong>，並以佔例反覆驗證、修正、傳授。也因此，《高島易斷》更像一本「可對照的佔例教材」。</p><blockquote><p>提醒：傳記與佔例往往帶有敘事誇張與時代立場（含戰事與政治背景）。閱讀時宜保持史觀與批判性，取其方法之長。</p></blockquote><h2 id="本-app-收錄內容-依卦呈現" tabindex="-1">本 App 收錄內容（依卦呈現） <a class="header-anchor" href="#本-app-收錄內容-依卦呈現" aria-label="Permalink to “本 App 收錄內容（依卦呈現）”">​</a></h2><ul><li><strong>卦名解讀</strong>：先交代卦名與卦象結構，建立閱讀入口</li><li><strong>卦辭 / 象辭</strong>：提供原典對應的要點文本</li><li><strong>佔斷（高島易斷）</strong>：每卦的精煉佔解條目</li><li><strong>爻變詳解</strong>：逐爻的變化解讀與佔例整理</li></ul><p>本頁所示內容與圖片僅供學習與參考；原書文本為公版資料。</p><hr><h1 id="焦氏易林" tabindex="-1">焦氏易林 <a class="header-anchor" href="#焦氏易林" aria-label="Permalink to “焦氏易林”">​</a></h1><p>《焦氏易林》又稱《易林》，傳為西漢易學家 <strong>焦延壽（字贛）</strong> 所作的詩體佔書（作者歸屬亦有不同說法）。 它以《周易》六十四卦為基礎，將「本卦 → 之卦」的組合系統化：<strong>每一卦各衍生六十四卦</strong>，合成 <strong>64×64＝4096</strong> 條佔辭， 多用<strong>四言韻語</strong>呈現，把抽象卦象轉寫成更具畫面感的意象與情境。</p><h2 id="與《周易》的故事線" tabindex="-1">與《周易》的故事線 <a class="header-anchor" href="#與《周易》的故事線" aria-label="Permalink to “與《周易》的故事線”">​</a></h2><p>《周易》重在卦象與卦爻辭的義理結構；而《易林》則像是一套「把卦意變成可讀的詩句」的占筮語料庫：</p><ul><li>以詩句補足卦象的情境（人事、物象、吉凶、得失）</li><li>讓佔斷更容易抓住「象」與「機」</li><li>也成為後世象數易學與占筮實作的重要材料之一</li></ul><h2 id="本-app-如何使用《易林》" tabindex="-1">本 App 如何使用《易林》 <a class="header-anchor" href="#本-app-如何使用《易林》" aria-label="Permalink to “本 App 如何使用《易林》”">​</a></h2><p>本 App 會依你佔得的「本卦 → 之卦」自動顯示對應詩句，用來輔助解讀：</p><ol><li>先抓詩中的關鍵意象（人物、動作、地點、器物、吉凶詞）</li><li>再對照你的問題脈絡與當下處境</li><li>最後回到《周易》卦象與動爻，做整體判斷</li></ol><h2 id="翻譯說明" tabindex="-1">翻譯說明 <a class="header-anchor" href="#翻譯說明" aria-label="Permalink to “翻譯說明”">​</a></h2><p>英文詩句為中文整理翻譯而來，偏直譯；中文仍應作為主要依據，英文僅供參考。</p><ul><li>讀法：先觀詩中關鍵意象，再結合當事問題、卦象與動爻綜合判讀。</li><li>來源說明：英文翻譯從中文本《焦氏易林》整理翻譯而來，詩句以直譯為主，難以完全傳達中文之準確含義；以中文為準，英文僅供參考。</li></ul>',34)])])}const b=r(l,[["render",o]]);export{c as __pageData,b as default};
